import time

def retry(fn, tries=3, base=0.1):
    last = None
    for i in range(tries):
        try:
            return fn()
        except Exception as e:
            last = e
            time.sleep(base * (2 ** i))
    raise last

assert retry(lambda: 42) == 42
```

